@startuml
state Outer {
state Inner {
state Leaf
}
}
Outer --> Done
@enduml

@startuml
package P {
package Q {
class A
}
class B
}
A --> B
@enduml

@startuml
map M {
a *-> A
b *-> B
}
A --> B
@enduml

@startuml
object A
note right of A: first
note right of A: second
@enduml

@startuml
if (ready) then (yes)
if (ok) then (yes)
:work;
else (no)
:retry;
endif
else (no)
:stop;
endif
@enduml

@startuml
state Parallel {
state Left
--
state Right
}
Left --> Right
@enduml

@startuml
map M {
a *-> A
b *-> A
}
A --> A
@enduml

@startuml
map M {
a *-> A
a *-> B
}
@enduml
